// Repository abstraction shape (SQLite impl lands with rusqlite installed).
pub trait VaultRepo {
    type Error;
    fn insert(&mut self, service: &str, username: &str, secret: &str) -> Result<i64, Self::Error>;
    fn list(&self) -> Result<Vec<(i64, String, String)>, Self::Error>; // id, service, masked
    fn delete(&mut self, id: i64) -> Result<bool, Self::Error>;
}

pub fn mask(secret: &str) -> String {
    let visible = secret.chars().take(2).collect::<String>();
    format!("{visible}{}", "*".repeat(secret.len().saturating_sub(2).min(12)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn masks_long_secrets() {
        assert_eq!(mask("hunter2"), "hu****");
    }
}
